from functools import total_ordering

@total_ordering
class Money:
    def __init__(self, cents):
        self.cents = cents
    def __eq__(self, o):
        if not isinstance(o, Money):
            return NotImplemented
        return self.cents == o.cents
    def __lt__(self, o):
        if not isinstance(o, Money):
            return NotImplemented
        return self.cents < o.cents
    def __add__(self, o):
        if not isinstance(o, Money):
            return NotImplemented
        return Money(self.cents + o.cents)
    def __radd__(self, o):
        return self if o == 0 else NotImplemented
    def __repr__(self):
        return f"Money({self.cents})"

print(sorted([Money(5), Money(1), Money(3)]))
print(Money(1) <= Money(2), Money(2) >= Money(3))
print(sum([Money(1), Money(2)]))
print(Money(1) == 5)
try:
    Money(1) + 5
except TypeError:
    print("TypeError")

