class Playlist:
    def __init__(self, *songs):
        self._s = list(songs)
    def __len__(self):
        return len(self._s)
    def __getitem__(self, i):
        return self._s[i]
    def __contains__(self, x):
        return x in self._s
    def __iter__(self):
        return iter(self._s)

p = Playlist("a", "b", "c")
print(len(p), p[0], p[-1], p[1:], "b" in p, list(p), bool(Playlist()))

