from collections import OrderedDict

class LRU:
    def __init__(self, cap):
        if cap <= 0:
            raise ValueError("cap must be positive")
        self.cap = cap
        self.d = OrderedDict()

    def get(self, k, default=None):
        if k not in self.d:
            return default
        self.d.move_to_end(k)
        return self.d[k]

    def put(self, k, v):
        self.d[k] = v
        self.d.move_to_end(k)
        if len(self.d) > self.cap:
            self.d.popitem(last=False)

c = LRU(2)
c.put("a", 1)
c.put("b", 2)
c.get("a")
c.put("c", 3)
print(list(c.d), c.get("b"), c.get("a"))
